CREATE TABLE "AuthSession" ("id" TEXT NOT NULL PRIMARY KEY,"userId" INTEGER NOT NULL,"deviceName" TEXT NOT NULL,"platform" TEXT NOT NULL,"userAgent" TEXT NOT NULL DEFAULT '',"ipAddress" TEXT NOT NULL DEFAULT '',"loginMethod" TEXT NOT NULL DEFAULT 'password',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeenAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" DATETIME NOT NULL,"revokedAt" DATETIME,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AuthSession_userId_revokedAt_lastSeenAt_idx" ON "AuthSession"("userId","revokedAt","lastSeenAt");
CREATE INDEX "AuthSession_expiresAt_idx" ON "AuthSession"("expiresAt");
CREATE TABLE "LoginEvent" ("id" TEXT NOT NULL PRIMARY KEY,"userId" INTEGER,"email" TEXT NOT NULL,"result" TEXT NOT NULL,"method" TEXT NOT NULL DEFAULT 'password',"ipAddress" TEXT NOT NULL DEFAULT '',"userAgent" TEXT NOT NULL DEFAULT '',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "LoginEvent_userId_createdAt_idx" ON "LoginEvent"("userId","createdAt");
CREATE INDEX "LoginEvent_email_createdAt_idx" ON "LoginEvent"("email","createdAt");
CREATE TABLE "TotpCredential" ("id" TEXT NOT NULL PRIMARY KEY,"userId" INTEGER NOT NULL UNIQUE,"secretEncrypted" TEXT NOT NULL,"enabledAt" DATETIME,"recoveryCodesJson" TEXT NOT NULL DEFAULT '[]',"lastUsedCounter" INTEGER NOT NULL DEFAULT -1,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "PasskeyCredential" ("id" TEXT NOT NULL PRIMARY KEY,"userId" INTEGER NOT NULL,"credentialId" TEXT NOT NULL UNIQUE,"publicKey" TEXT NOT NULL,"signCount" INTEGER NOT NULL DEFAULT 0,"transports" TEXT NOT NULL DEFAULT '[]',"name" TEXT NOT NULL DEFAULT 'Passkey',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastUsedAt" DATETIME,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "PasskeyCredential_userId_createdAt_idx" ON "PasskeyCredential"("userId","createdAt");
CREATE TABLE "AuthChallenge" ("id" TEXT NOT NULL PRIMARY KEY,"userId" INTEGER NOT NULL,"challenge" TEXT NOT NULL UNIQUE,"purpose" TEXT NOT NULL,"expiresAt" DATETIME NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AuthChallenge_userId_purpose_expiresAt_idx" ON "AuthChallenge"("userId","purpose","expiresAt");
